for (const [i,old] of before.entries.entries()) {
  const now = after.entries[i];
  assert.equal(now.id,old.id);
  if (JSON.stringify(old) === JSON.stringify(now)) continue;
  changed.push(old.id);
  assert.ok(expected.has(old.id), old.id);
  assert.deepEqual(Object.keys(now),Object.keys(old), "'`${old.id} shape`);
  for (const field of ['"'buying_tips','watch_out','sources']) {
    if (old[field]) assert.deepEqual(now[field].slice(0,old[field].length),old[field], "'`${old.id}.${field} original order`);
